import re, zlib
p = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_15/3M_2018_10K.pdf"
data = open(p, "rb").read()

# Extract all stream objects
def get_streams(data):
    out = []
    for m in re.finditer(rb"stream\r?\n", data):
        start = m.end()
        end = data.find(b"endstream", start)
        if end == -1:
            continue
        raw = data[start:end]
        # strip trailing newline before endstream
        if raw.endswith(b"\r\n"):
            raw = raw[:-2]
        elif raw.endswith(b"\n"):
            raw = raw[:-1]
        elif raw.endswith(b"\r"):
            raw = raw[:-1]
        out.append(raw)
    return out

streams = get_streams(data)
print("num streams:", len(streams))
# Try decompressing each and see which contain text operators
for i, s in enumerate(streams):
    try:
        d = zlib.decompress(s)
    except Exception as e:
        continue
    if b"Tj" in d or b"TJ" in d:
        print("stream", i, "len", len(d), "has text")
